import * as THREE from 'three/webgpu';
import { texture, uv, vec2, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-2-label';

  const pos = config.position || [0, 1, 0.06];
  const rot = config.rotation || [0, 0, 0];
  const scl = config.scale || [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  // Atlas region params
  const atlasSize = vec2(512, 512);
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const uvOffset = new THREE.Vector2(rect.x / 512, 1 - (rect.y + rect.h) / 512);
  const uvScale = new THREE.Vector2(rect.w / 512, rect.h / 512);

  const aspect = rect.w / rect.h;
  const planeHeight = 0.34;
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const uvOffsetUniform = uniform(uvOffset);
  const uvScaleUniform = uniform(uvScale);
  const mappedUV = uv().mul(uvScaleUniform).add(uvOffsetUniform);

  const material = new THREE.MeshBasicNodeMaterial();
  material.map = map;
  material.mapNode = texture(map, mappedUV);
  material.transparent = true;

  const bgMesh = new THREE.Mesh(geometry, material);
  bgMesh.name = 'card-label-bg';
  group.add(bgMesh);

  // MSDF text content: "Pricing 2"
  let textMesh = null;
  try {
    textMesh = ctx.fontAtlas.createText({
      text: 'Pricing 2',
      font: 'display',
      weight: 400,
      size: 0.34 * (39 / 62),
      color: config.colors?.paper || '#e8ecf2',
      align: 'center',
      anchor: 'center',
    });
    textMesh.name = 'card-label-text';
    textMesh.position.set(0, 0, 0.001);
    group.add(textMesh);
  } catch (e) {
    // fontAtlas may throw if unavailable; fail gracefully
  }

  // Billboard toward camera each frame
  const onBeforeRender = (renderer, scene, camera) => {
    group.quaternion.copy(camera.quaternion);
  };
  group.onBeforeRender = onBeforeRender;

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
  };

  return group;
}
